// Sunset City — procedural city world
// Original code and art. No game assets are copied from any commercial title.

export const CELL = 560;
export const ROAD_HALF = 58;
export const GRID = 8;
export const WORLD = CELL * GRID;
export const SIDEWALK = 22;
export const LANE = 26;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  const r = clamp(((n >> 16) & 255) + amt, 0, 255);
  const g = clamp(((n >> 8) & 255) + amt, 0, 255);
  const b = clamp((n & 255) + amt, 0, 255);
  return `rgb(${r},${g},${b})`;
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

const BUILDING_COLORS = [
  '#8d99ae', '#b08968', '#c9ada7', '#9a8c98', '#b5a58c',
  '#7f8c8d', '#c07f6a', '#a3b18a', '#bfa58a', '#8ea6b4',
  '#d4a373', '#a68a7a', '#ad9d8f', '#97a1a8', '#c19a6b',
];

export class City {
  constructor(seed = 20131) {
    this.rng = mulberry32(seed);
    this.blocks = [];
    this.buildings = [];
    this.trees = [];
    this.spots = [];
    this.buckets = new Map();
    this.generate();
  }

  bucketKey(i, j) { return i + ',' + j; }

  generate() {
    const rng = this.rng;
    for (let j = 0; j < GRID; j++) {
      for (let i = 0; i < GRID; i++) {
        const x0 = i * CELL + ROAD_HALF;
        const y0 = j * CELL + ROAD_HALF;
        const w = CELL - ROAD_HALF * 2;
        const roll = rng();
        const type = roll < 0.1 ? 'park' : roll < 0.2 ? 'lot' : 'city';
        const inner = { x: x0 + SIDEWALK, y: y0 + SIDEWALK, w: w - SIDEWALK * 2, h: w - SIDEWALK * 2 };
        const block = { i, j, x: x0, y: y0, w, h: w, type, inner };
        this.blocks.push(block);

        if (type === 'park') this.addPark(block);
        else if (type === 'lot') this.addLot(block);
        else this.addBuildings(block);
      }
    }
  }

  addPark(block) {
    const rng = this.rng;
    const { inner } = block;
    block.pond = rng() < 0.4
      ? { x: inner.x + 70 + rng() * (inner.w - 140), y: inner.y + 80 + rng() * (inner.h - 160), r: 28 + rng() * 18 }
      : null;
    const count = 7 + Math.floor(rng() * 6);
    for (let k = 0; k < count; k++) {
      const t = {
        x: inner.x + 24 + rng() * (inner.w - 48),
        y: inner.y + 24 + rng() * (inner.h - 48),
        r: 13 + rng() * 11,
        tone: rng(),
      };
      const cx = inner.x + inner.w / 2;
      const cy = inner.y + inner.h / 2;
      if (Math.abs(t.x - cx) < 34 || Math.abs(t.y - cy) < 34) continue;
      if (block.pond && Math.hypot(t.x - block.pond.x, t.y - block.pond.y) < block.pond.r + t.r + 8) continue;
      this.trees.push(t);
    }
  }

  addLot(block) {
    const rng = this.rng;
    const { inner } = block;
    const rows = 2;
    const cols = 4;
    const cw = inner.w / cols;
    const ch = inner.h / rows;
    block.stalls = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const cx = inner.x + cw * (c + 0.5);
        const cy = inner.y + ch * (r + 0.5);
        const angle = r === 0 ? Math.PI / 2 : -Math.PI / 2;
        block.stalls.push({ x: cx, y: cy, angle });
        if (rng() < 0.55) this.spots.push({ x: cx, y: cy, angle });
      }
    }
  }

  addBuildings(block) {
    const rng = this.rng;
    const { inner } = block;
    const zone = { x: inner.x + 6, y: inner.y + 6, w: inner.w - 12, h: inner.h - 12 };
    const layouts = [
      [[0, 0, 1, 1]],
      [[0, 0, 1, 0.5], [0, 0.5, 1, 0.5]],
      [[0, 0, 0.5, 1], [0.5, 0, 0.5, 1]],
      [[0, 0, 0.5, 0.5], [0.5, 0, 0.5, 0.5], [0, 0.5, 0.5, 0.5], [0.5, 0.5, 0.5, 0.5]],
    ];
    const layout = layouts[Math.floor(rng() * layouts.length)];
    const gap = 14 + rng() * 10;

    for (const [lx, ly, lw, lh] of layout) {
      let x = zone.x + lx * zone.w;
      let y = zone.y + ly * zone.h;
      let w = lw * zone.w;
      let h = lh * zone.h;
      const padX = gap * (lx === 0 ? 0 : 0.5);
      const padY = gap * (ly === 0 ? 0 : 0.5);
      x += padX; y += padY;
      w -= padX + (lx + lw >= 0.999 ? 0 : gap * 0.5);
      h -= padY + (ly + lh >= 0.999 ? 0 : gap * 0.5);
      if (w < 54 || h < 54) continue;
      const shrink = 2 + rng() * 5;
      x += shrink; y += shrink; w -= shrink * 2; h -= shrink * 2;
      const stories = 1 + Math.floor(rng() * 5);
      const color = BUILDING_COLORS[Math.floor(rng() * BUILDING_COLORS.length)];
      const b = {
        x, y, w, h, stories, color,
        roof: shade(color, -30),
        edge: shade(color, 34),
        props: [],
        sign: null,
      };
      const propCount = 1 + Math.floor(rng() * 4);
      for (let p = 0; p < propCount; p++) {
        if (w < 80 || h < 80) break;
        b.props.push({
          x: x + 10 + rng() * (w - 50),
          y: y + 10 + rng() * (h - 50),
          w: 9 + rng() * 16,
          h: 7 + rng() * 12,
          kind: rng() < 0.25 ? 'tank' : 'ac',
        });
      }
      if (rng() < 0.12 && w > 90) {
        b.sign = {
          color: rng() < 0.5 ? '#ff4d9d' : rng() < 0.5 ? '#34d6ff' : '#ffc857',
          x: x + 12,
          y: y + 6,
          w: 34 + rng() * 30,
        };
      }
      this.buildings.push(b);
      const key = this.bucketKey(block.i, block.j);
      if (!this.buckets.has(key)) this.buckets.set(key, []);
      this.buckets.get(key).push(b);
    }
  }

  buildingsNear(x, y) {
    const bi = Math.floor(x / CELL);
    const bj = Math.floor(y / CELL);
    let out = null;
    for (let j = bj - 1; j <= bj + 1; j++) {
      for (let i = bi - 1; i <= bi + 1; i++) {
        const arr = this.buckets.get(this.bucketKey(i, j));
        if (arr) out = out ? out.concat(arr) : arr;
      }
    }
    return out || [];
  }

  // Push a circle out of every building it overlaps. Returns corrected position.
  resolveCircle(x, y, r) {
    let hit = false;
    const list = this.buildingsNear(x, y);
    for (let k = 0; k < list.length; k++) {
      const b = list[k];
      const nx = clamp(x, b.x, b.x + b.w);
      const ny = clamp(y, b.y, b.y + b.h);
      let dx = x - nx;
      let dy = y - ny;
      const d2 = dx * dx + dy * dy;
      if (d2 >= r * r) continue;
      hit = true;
      if (d2 > 0.0001) {
        const d = Math.sqrt(d2);
        x = nx + (dx / d) * r;
        y = ny + (dy / d) * r;
      } else {
        const left = x - b.x;
        const right = b.x + b.w - x;
        const top = y - b.y;
        const bottom = b.y + b.h - y;
        const m = Math.min(left, right, top, bottom);
        if (m === left) x = b.x - r;
        else if (m === right) x = b.x + b.w + r;
        else if (m === top) y = b.y - r;
        else y = b.y + b.h + r;
      }
    }
    x = clamp(x, 16, WORLD - 16);
    y = clamp(y, 16, WORLD - 16);
    return { x, y, hit };
  }

  pointBlocked(x, y, r = 10) {
    const list = this.buildingsNear(x, y);
    for (let k = 0; k < list.length; k++) {
      const b = list[k];
      if (x > b.x - r && x < b.x + b.w + r && y > b.y - r && y < b.y + b.h + r) return true;
    }
    return false;
  }

  // A random point on a road (used for traffic, cops, deliveries).
  randomRoadPoint(rng = Math.random) {
    const vertical = rng() < 0.5;
    const road = Math.floor(rng() * (GRID + 1));
    const along = 80 + rng() * (WORLD - 160);
    const lane = (rng() < 0.5 ? -1 : 1) * LANE;
    const c = road * CELL;
    return vertical
      ? { x: c + lane, y: along, road, vertical }
      : { x: along, y: c + lane, road, vertical };
  }

  nearestSpot(x, y) {
    let best = null;
    let bd = Infinity;
    for (const s of this.spots) {
      const d = (s.x - x) ** 2 + (s.y - y) ** 2;
      if (d < bd) { bd = d; best = s; }
    }
    return best;
  }

  drawGround(ctx, view) {
    ctx.fillStyle = '#2b2e35';
    ctx.fillRect(view.x, view.y, view.w, view.h);

    const i0 = Math.max(0, Math.floor(view.x / CELL) - 1);
    const i1 = Math.min(GRID - 1, Math.floor((view.x + view.w) / CELL) + 1);
    const j0 = Math.max(0, Math.floor(view.y / CELL) - 1);
    const j1 = Math.min(GRID - 1, Math.floor((view.y + view.h) / CELL) + 1);

    for (const block of this.blocks) {
      if (block.i < i0 || block.i > i1 || block.j < j0 || block.j > j1) continue;
      this.drawBlock(ctx, block, view);
    }

    this.drawMarkings(ctx, view);
  }

  drawBlock(ctx, block, view) {
    const { x, y, w, h, inner } = block;
    // Sidewalk slab
    ctx.fillStyle = '#67655f';
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = '#7b786f';
    ctx.fillRect(x + 3, y + 3, w - 6, h - 6);
    // Curb line
    ctx.strokeStyle = 'rgba(20,20,24,0.35)';
    ctx.lineWidth = 2;
    ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);

    if (block.type === 'park') {
      this.drawPark(ctx, block);
    } else if (block.type === 'lot') {
      ctx.fillStyle = '#3b3e46';
      ctx.fillRect(inner.x, inner.y, inner.w, inner.h);
      ctx.strokeStyle = 'rgba(226,226,210,0.35)';
      ctx.lineWidth = 2;
      if (block.stalls) {
        for (const s of block.stalls) {
          ctx.save();
          ctx.translate(s.x, s.y);
          ctx.rotate(s.angle);
          ctx.strokeRect(-24, -30, 48, 60);
          ctx.restore();
        }
      }
      ctx.strokeStyle = 'rgba(226,226,210,0.5)';
      ctx.strokeRect(inner.x + 2, inner.y + 2, inner.w - 4, inner.h - 4);
    } else {
      ctx.fillStyle = '#5f5d58';
      ctx.fillRect(inner.x, inner.y, inner.w, inner.h);
      ctx.strokeStyle = 'rgba(0,0,0,0.12)';
      ctx.lineWidth = 1;
      for (let gx = inner.x; gx < inner.x + inner.w; gx += 40) {
        ctx.beginPath();
        ctx.moveTo(gx, inner.y);
        ctx.lineTo(gx, inner.y + inner.h);
        ctx.stroke();
      }
      for (const b of this.buildings) {
        if (b.x < block.x - 5 || b.x > block.x + block.w) continue;
        if (b.y < block.y - 5 || b.y > block.y + block.h) continue;
        this.drawBuilding(ctx, b, view);
      }
    }
  }

  drawPark(ctx, block) {
    const { inner } = block;
    ctx.fillStyle = '#446b4c';
    ctx.fillRect(inner.x, inner.y, inner.w, inner.h);
    ctx.fillStyle = '#4b7654';
    ctx.fillRect(inner.x + 4, inner.y + 4, inner.w - 8, inner.h - 8);

    // paths
    ctx.fillStyle = '#8c8375';
    ctx.fillRect(inner.x + inner.w / 2 - 13, inner.y, 26, inner.h);
    ctx.fillRect(inner.x, inner.y + inner.h / 2 - 13, inner.w, 26);

    if (block.pond) {
      const p = block.pond;
      ctx.fillStyle = '#2c5566';
      ctx.beginPath();
      ctx.ellipse(p.x, p.y, p.r * 1.15, p.r * 0.85, 0.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(150,220,230,0.25)';
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    for (const t of this.trees) {
      if (t.x < block.x || t.x > block.x + block.w || t.y < block.y || t.y > block.y + block.h) continue;
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath();
      ctx.ellipse(t.x + 7, t.y + 8, t.r * 1.05, t.r * 0.9, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3d6440';
      ctx.beginPath();
      ctx.arc(t.x, t.y, t.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = t.tone > 0.5 ? '#568a55' : '#4e7d4f';
      ctx.beginPath();
      ctx.arc(t.x - t.r * 0.22, t.y - t.r * 0.22, t.r * 0.82, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(160,210,140,0.35)';
      ctx.beginPath();
      ctx.arc(t.x - t.r * 0.35, t.y - t.r * 0.35, t.r * 0.32, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  drawBuilding(ctx, b, view) {
    if (b.x > view.x + view.w + 40 || b.x + b.w < view.x - 40) return;
    if (b.y > view.y + view.h + 40 || b.y + b.h < view.y - 40) return;
    const off = 5 + b.stories * 2.4;

    ctx.fillStyle = 'rgba(10,10,14,0.35)';
    ctx.fillRect(b.x + off, b.y + off, b.w, b.h);

    ctx.fillStyle = b.color;
    ctx.fillRect(b.x, b.y, b.w, b.h);

    // Facade lip: light on top-left, dark on bottom-right
    ctx.fillStyle = b.edge;
    ctx.fillRect(b.x, b.y, b.w, 4);
    ctx.fillRect(b.x, b.y, 4, b.h);
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    ctx.fillRect(b.x, b.y + b.h - 4, b.w, 4);
    ctx.fillRect(b.x + b.w - 4, b.y, 4, b.h);

    // Roof
    ctx.fillStyle = b.roof;
    ctx.fillRect(b.x + 7, b.y + 7, b.w - 14, b.h - 14);
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    ctx.strokeRect(b.x + 7.5, b.y + 7.5, b.w - 15, b.h - 15);

    // Rooftop props
    for (const p of b.props) {
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      ctx.fillRect(p.x + 3, p.y + 3, p.w, p.h);
      ctx.fillStyle = p.kind === 'tank' ? '#9c8f7d' : '#8b9095';
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = 'rgba(255,255,255,0.18)';
      ctx.fillRect(p.x, p.y, p.w, 2);
      if (p.kind === 'ac') {
        ctx.strokeStyle = 'rgba(30,30,35,0.4)';
        ctx.strokeRect(p.x + 2.5, p.y + 2.5, p.w - 5, p.h - 5);
      } else {
        ctx.beginPath();
        ctx.arc(p.x + p.w / 2, p.y + p.h / 2, Math.min(p.w, p.h) / 2.4, 0, Math.PI * 2);
        ctx.fillStyle = '#6f6558';
        ctx.fill();
      }
    }

    // Neon sign
    if (b.sign) {
      ctx.save();
      ctx.shadowColor = b.sign.color;
      ctx.shadowBlur = 14;
      ctx.fillStyle = b.sign.color;
      ctx.fillRect(b.sign.x, b.sign.y, b.sign.w, 4);
      ctx.shadowBlur = 0;
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.fillRect(b.sign.x + 3, b.sign.y + 1, b.sign.w - 6, 1.5);
      ctx.restore();
    }
  }

  drawMarkings(ctx, view) {
    const i0 = Math.max(0, Math.floor(view.x / CELL) - 1);
    const i1 = Math.min(GRID, Math.floor((view.x + view.w) / CELL) + 1);
    const j0 = Math.max(0, Math.floor(view.y / CELL) - 1);
    const j1 = Math.min(GRID, Math.floor((view.y + view.h) / CELL) + 1);

    ctx.lineCap = 'round';

    // Vertical roads
    for (let i = i0; i <= i1; i++) {
      const x = i * CELL;
      if (x < view.x - 80 || x > view.x + view.w + 80) continue;
      for (let j = 0; j <= GRID; j++) {
        const y0 = j === 0 ? 0 : j * CELL + ROAD_HALF + 8;
        const y1 = j === GRID ? WORLD : j * CELL - ROAD_HALF - 8;
        if (y1 <= y0) continue;
        if (y0 > view.y + view.h || y1 < view.y) continue;
        ctx.strokeStyle = 'rgba(230,228,220,0.5)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x - ROAD_HALF + 7, Math.max(y0, view.y));
        ctx.lineTo(x - ROAD_HALF + 7, Math.min(y1, view.y + view.h));
        ctx.moveTo(x + ROAD_HALF - 7, Math.max(y0, view.y));
        ctx.lineTo(x + ROAD_HALF - 7, Math.min(y1, view.y + view.h));
        ctx.stroke();
        // dashed centre
        ctx.strokeStyle = 'rgba(224,180,74,0.75)';
        ctx.lineWidth = 3;
        ctx.setLineDash([26, 26]);
        ctx.beginPath();
        ctx.moveTo(x, Math.max(y0, view.y));
        ctx.lineTo(x, Math.min(y1, view.y + view.h));
        ctx.stroke();
        ctx.setLineDash([]);
      }
    }

    // Horizontal roads
    for (let j = j0; j <= j1; j++) {
      const y = j * CELL;
      if (y < view.y - 80 || y > view.y + view.h + 80) continue;
      for (let i = 0; i <= GRID; i++) {
        const x0 = i === 0 ? 0 : i * CELL + ROAD_HALF + 8;
        const x1 = i === GRID ? WORLD : i * CELL - ROAD_HALF - 8;
        if (x1 <= x0) continue;
        if (x0 > view.x + view.w || x1 < view.x) continue;
        ctx.strokeStyle = 'rgba(230,228,220,0.5)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(Math.max(x0, view.x), y - ROAD_HALF + 7);
        ctx.lineTo(Math.min(x1, view.x + view.w), y - ROAD_HALF + 7);
        ctx.moveTo(Math.max(x0, view.x), y + ROAD_HALF - 7);
        ctx.lineTo(Math.min(x1, view.x + view.w), y + ROAD_HALF - 7);
        ctx.stroke();
        ctx.strokeStyle = 'rgba(224,180,74,0.75)';
        ctx.lineWidth = 3;
        ctx.setLineDash([26, 26]);
        ctx.beginPath();
        ctx.moveTo(Math.max(x0, view.x), y);
        ctx.lineTo(Math.min(x1, view.x + view.w), y);
        ctx.stroke();
        ctx.setLineDash([]);
      }
    }

    // Crosswalks
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        const cx = i * CELL;
        const cy = j * CELL;
        if (cx < view.x - 100 || cx > view.x + view.w + 100) continue;
        if (cy < view.y - 100 || cy > view.y + view.h + 100) continue;
        ctx.fillStyle = 'rgba(235,233,226,0.42)';
        for (let s = -3; s <= 3; s++) {
          const o = s * 13;
          ctx.fillRect(cx - ROAD_HALF - 26, cy + o - 4, 20, 8);
          ctx.fillRect(cx + ROAD_HALF + 6, cy + o - 4, 20, 8);
          ctx.fillRect(cx + o - 4, cy - ROAD_HALF - 26, 8, 20);
          ctx.fillRect(cx + o - 4, cy + ROAD_HALF + 6, 8, 20);
        }
      }
    }
  }
}

// Input: keyboard, mouse aim and touch controls.
export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.joy = { x: 0, y: 0, active: false, id: null };
    this.keyX = 0;
    this.keyY = 0;
    this.keyThrottle = 0;
    this.keySteer = 0;
    this.fireHeld = false;
    this.mouse = { x: 0, y: 0, active: false, down: false };
    this.pressed = new Set();
    this.touch = matchMedia('(pointer: coarse)').matches;
    this.moveX = 0;
    this.moveY = 0;
    this.throttle = 0;
    this.steer = 0;

    this.bindKeyboard();
    this.bindMouse();
    this.bindTouch();
  }

  bindKeyboard() {
    const block = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space']);
    window.addEventListener('keydown', (e) => {
      if (block.has(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      if (e.code === 'KeyE') this.pressed.add('enter');
      if (e.code === 'KeyF' || e.code === 'Space') this.pressed.add('fire');
      if (e.code === 'Escape' || e.code === 'KeyP') this.pressed.add('pause');
      if (e.code === 'KeyM') this.pressed.add('mute');
      if (e.code === 'Enter') this.pressed.add('start');
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.fireHeld = false;
      this.joy.x = 0;
      this.joy.y = 0;
    });
  }

  bindMouse() {
    const c = this.canvas;
    window.addEventListener('mousemove', (e) => {
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
      if (e.pointerType !== 'touch') this.mouse.active = true;
    });
    c.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'touch') return;
      if (e.button !== 0) return;
      this.mouse.down = true;
      this.fireHeld = true;
      this.pressed.add('fire');
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
    });
    window.addEventListener('pointerup', (e) => {
      if (e.pointerType === 'touch') return;
      this.mouse.down = false;
      this.fireHeld = false;
    });
    c.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  bindTouch() {
    const base = document.getElementById('stick');
    const knob = document.getElementById('knob');
    if (!base || !knob) return;
    const rectOf = () => base.getBoundingClientRect();
    const move = (e) => {
      const r = rectOf();
      const cx = r.left + r.width / 2;
      const cy = r.top + r.height / 2;
      let dx = (e.clientX - cx) / (r.width / 2);
      let dy = (e.clientY - cy) / (r.height / 2);
      const len = Math.hypot(dx, dy);
      if (len > 1) { dx /= len; dy /= len; }
      this.joy.x = dx;
      this.joy.y = dy;
      this.joy.active = true;
      knob.style.transform = `translate(${dx * 46}px, ${dy * 46}px)`;
    };
    const end = () => {
      this.joy.x = 0; this.joy.y = 0; this.joy.active = false; this.joy.id = null;
      knob.style.transform = 'translate(0px, 0px)';
    };
    base.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      base.setPointerCapture(e.pointerId);
      this.joy.id = e.pointerId;
      move(e);
    });
    base.addEventListener('pointermove', (e) => {
      if (this.joy.id !== e.pointerId) return;
      e.preventDefault();
      move(e);
    });
    base.addEventListener('pointerup', (e) => {
      if (this.joy.id === e.pointerId) end();
    });
    base.addEventListener('pointercancel', end);
    base.addEventListener('lostpointercapture', end);

    for (const btn of document.querySelectorAll('[data-action]')) {
      btn.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        btn.classList.add('down');
        const a = btn.dataset.action;
        if (a === 'fire') { this.fireHeld = true; this.pressed.add('fire'); }
        else if (a === 'enter') this.pressed.add('enter');
        else if (a === 'brake') this.pressed.add('handbrake');
        else if (a === 'pause') this.pressed.add('pause');
        else if (a === 'mute') this.pressed.add('mute');
      });
      const up = (e) => {
        e.preventDefault();
        btn.classList.remove('down');
        if (btn.dataset.action === 'fire') this.fireHeld = false;
      };
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('pointerleave', up);
    }
  }

  update() {
    const k = this.keys;
    let kx = 0;
    let ky = 0;
    if (k.has('KeyA') || k.has('ArrowLeft')) kx -= 1;
    if (k.has('KeyD') || k.has('ArrowRight')) kx += 1;
    if (k.has('KeyW') || k.has('ArrowUp')) ky -= 1;
    if (k.has('KeyS') || k.has('ArrowDown')) ky += 1;

    let jx = this.joy.x;
    let jy = this.joy.y;
    if (Math.hypot(jx, jy) < 0.16) { jx = 0; jy = 0; }

    this.moveX = Math.abs(jx) > Math.abs(kx) ? jx : kx;
    this.moveY = Math.abs(jy) > Math.abs(ky) ? jy : ky;
    const ml = Math.hypot(this.moveX, this.moveY);
    if (ml > 1) { this.moveX /= ml; this.moveY /= ml; }

    // Driving: analog stick (push up to accelerate) or keys.
    this.throttle = ky !== 0 ? -ky : -jy;
    this.steer = kx !== 0 ? kx : jx;
    this.throttle = Math.max(-1, Math.min(1, this.throttle));
    this.steer = Math.max(-1, Math.min(1, this.steer));

    this.handbrake = k.has('ShiftLeft') || k.has('ShiftRight') || this.pressed.has('handbrake');
    this.sprint = k.has('ShiftLeft') || k.has('ShiftRight');
  }

  consume(action) {
    if (!this.pressed.has(action)) return false;
    this.pressed.delete(action);
    return true;
  }

  endFrame() {
    this.pressed.clear();
  }

  showTouch(show) {
    const el = document.getElementById('touch');
    if (el) el.classList.toggle('hidden', !show);
  }
}

// Tiny synthesised audio: engine, siren and one-shot effects. No audio files.
export class Audio {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.started = false;
    this.engine = null;
    this.siren = null;
    this.sirenPhase = 0;
  }

  ensure() {
    if (this.ctx) return this.ctx;
    const C = window.AudioContext || window.webkitAudioContext;
    if (!C) return null;
    this.ctx = new C();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    this.master.connect(this.ctx.destination);

    // One second of noise for crashes and gunshots.
    const len = this.ctx.sampleRate;
    this.noise = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return this.ctx;
  }

  async start() {
    const ctx = this.ensure();
    if (!ctx) return;
    if (ctx.state === 'suspended') await ctx.resume();
    if (this.started) return;
    this.started = true;

    const engGain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 520;
    filter.Q.value = 2.4;
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = 52;
    osc.connect(filter);
    filter.connect(engGain);
    engGain.connect(this.master);
    engGain.gain.value = 0;
    osc.start();
    this.engine = { osc, gain: engGain, filter };

    const sirenGain = ctx.createGain();
    sirenGain.gain.value = 0;
    const sirenOsc = ctx.createOscillator();
    sirenOsc.type = 'square';
    sirenOsc.frequency.value = 660;
    const sirenFilter = ctx.createBiquadFilter();
    sirenFilter.type = 'lowpass';
    sirenFilter.frequency.value = 1400;
    sirenOsc.connect(sirenFilter);
    sirenFilter.connect(sirenGain);
    sirenGain.connect(this.master);
    sirenOsc.start();
    this.siren = { osc: sirenOsc, gain: sirenGain, phase: 0 };
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.55;
    return this.muted;
  }

  update(dt, { driving, speed, siren }) {
    if (!this.ctx) return;
    if (this.engine) {
      const t = this.ctx.currentTime;
      const target = driving ? 0.08 + Math.min(0.1, Math.abs(speed) / 4200) : 0;
      this.engine.gain.gain.setTargetAtTime(target, t, 0.08);
      this.engine.osc.frequency.setTargetAtTime(46 + Math.abs(speed) * 0.33, t, 0.08);
      this.engine.filter.frequency.setTargetAtTime(420 + Math.abs(speed) * 1.1, t, 0.1);
    }
    if (this.siren) {
      const t = this.ctx.currentTime;
      this.siren.gain.gain.setTargetAtTime(siren > 0 ? 0.035 : 0, t, 0.15);
      this.siren.phase += dt;
      if (this.siren.phase > 0.55) this.siren.phase = 0;
      const hi = this.siren.phase < 0.27;
      this.siren.osc.frequency.setTargetAtTime(hi ? 780 : 560, t, 0.02);
    }
  }

  burst({ dur = 0.18, freq = 900, q = 1, vol = 0.5, type = 'lowpass' }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = ctx.createGain();
    const t = ctx.currentTime;
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t);
    src.stop(t + dur);
  }

  gunshot() {
    this.burst({ dur: 0.14, freq: 1600, vol: 0.35 });
    this.burst({ dur: 0.1, freq: 220, vol: 0.3 });
  }

  crash(power = 1) {
    this.burst({ dur: 0.3, freq: 340, vol: 0.18 + 0.25 * power });
    this.burst({ dur: 0.18, freq: 90, vol: 0.3 * power });
  }

  explosion() {
    this.burst({ dur: 0.9, freq: 420, vol: 0.65 });
    this.burst({ dur: 0.7, freq: 70, vol: 0.5 });
  }

  ping(freq = 880) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(freq * 1.5, t + 0.12);
    gain.gain.setValueAtTime(0.16, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t);
    osc.stop(t + 0.3);
  }

  mission() {
    this.ping(660);
    setTimeout(() => this.ping(990), 120);
  }

  hurt() {
    this.burst({ dur: 0.25, freq: 180, vol: 0.25 });
  }
}

