spawnTrafficNear(px,py,minD=600,maxD=1600):
```js
for(let t=0;t<12;t++){
  const vertical=Math.random()<0.5;
  const road=1+Math.floor(Math.random()*(GRID-1));
  const along=rand(80,WORLD-80);
  const dir = vertical? (Math.random()<0.5?{x:0,y:1}:{x:0,y:-1}) : (Math.random()<0.5?{x:1,y:0}:{x:-1,y:0});
  const right={x:-dir.y,y:dir.x};
