updateTraffic:
```js
updateTraffic(dt){
 const focus = this.state==='menu'? this.cam : (this.player.car||this.player);
 for(const car of this.cars){
   if(car.driver!=='ai' || car.isPolice || car.burned) continue;
   const ai=car.ai;
   if(!ai || ai.mode!=='traffic') continue;
   if(dist(car.x,car.y,focus.x,focus.y)>2300){ this.recycleTraffic(car,focus); continue; }
   const d=dist(car.x,car.y,ai.target.x,ai.target.y);
   if(d<32){ this.advanceTraffic(car); }
   const ang=Math.atan2(ai.target.y-car.y, ai.target.x-car.x);
   car.angle=angLerp(car.angle,ang,4*dt*(0.5+Math.min(1,Math.abs(car.speed)/80)));
   // slow down if something ahead
   let desired=ai.limit;
   const fx=car.x+Math.cos(car.angle)*70, fy=car.y+Math.sin(car.angle)*70;
   for(const other of this.cars){
     if(other===car||other.burned) continue;
     if(dist(other.x,other.y,fx,fy)<52){ desired=Math.min(desired, Math.max(0,(dist(other.x,other.y,car.x,car.y)-45)*2)); }
   }
   car.speed=lerp(car.speed, desired, 1.8*dt);
   const c=Math.cos(car.angle), s=Math.sin(car.angle);
   car.x+=c*car.speed*dt; car.y+=s*car.speed*dt;
   const res=this.city.resolveCircle(car.x,car.y,car.w*0.6);
   if(res.hit){ car.x=res.x; car.y=res.y; car.speed*=0.5; }
   if(car.speed<12){ car.stall+=dt; if(car.stall>6) this.recycleTraffic(car,focus); } else car.stall=0;
 }
}
```
O(cars²) for traffic speed checks: 35²=1225, fine.

advanceTraffic:
```js
advanceTraffic(car){
 const ai=car.ai;
 ai.node=ai.nextNode;
 const straight={x:ai.dir.x,y:ai.dir.y};
 const options=[];
 const candidates=[
  {dir:straight,w:4},
  {dir:{x:-straight.y,y:straight.x},w:1.4},
  {dir:{x:straight.y,y:-straight.x},w:1.4},
 ];
 let total=0;
 for(const o of candidates){
  const ni=ai.node.i+o.dir.x, nj=ai.node.j+o.dir.y;
  if(ni<0||ni>GRID||nj<0||nj>GRID) continue;
  options.push({...o,next:{i:ni,j:nj}}); total+=o.w;
 }
 if(!options.length){ // dead end: reverse
   const dir={x:-straight.x,y:-straight.y};
   const ni=ai.node.i+dir.x, nj=ai.node.j+dir.y;
   if(ni<0||ni>GRID||nj<0||nj>GRID){ ai.dir=dir; ai.nextNode=ai.node; return; }
   options.push({dir,next:{i:ni,j:nj},w:1}); total=1;
 }
 let r=Math.random()*total; let chosen=options[options.length-1];
 for(const o of options){ r-=o.w; if(r<=0){chosen=o;break;} }
 ai.dir=chosen.dir; ai.nextNode=chosen.next; ai.target=this.laneTarget(chosen.next,chosen.dir);
}
```
Careful: `ai.nextNode` might equal node after reverse; laneTarget then target = lane offset of current node → car drives there and advances again. Fine.

