updatePeds(dt):
```js
const p=this.player;
for(const ped of this.peds){
  if(ped.down){ ped.downT-=dt; if(ped.downT<=0) ped.remove=true; continue; }
  const dPlayer=dist(ped.x,ped.y,p.x,p.y);
  if(dPlayer>2000){ ped.remove=true; this.spawnPedNear(p.x,p.y,1200); continue; } // careful mutate while iterating + spawn
  let speed=ped.speed;
  if(ped.scare>0){ ped.scare-=dt; const a=Math.atan2(ped.y-ped.scareY,ped.x-ped.scareX); ped.angle=angLerp(ped.angle,a,6*dt); speed=130; }
  else {
