:root {
  --ink: #0b0d13;
  --panel: rgba(14, 16, 23, 0.66);
  --line: rgba(255, 255, 255, 0.14);
  --orange: #ff7a2f;
  --pink: #ff3d7f;
  --cream: #ffe8c2;
  --cyan: #63e6ff;
  --gold: #ffd166;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: #fff;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#game {
  position: fixed;
  inset: 0;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(6, 6, 10, 0.5) 100%),
    linear-gradient(180deg, rgba(255, 120, 40, 0.045), transparent 32%, rgba(20, 10, 40, 0.1));
}

.hidden { display: none !important; }

/* ---------- HUD ---------- */
#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 16px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
}

.status {
  position: absolute;
  top: calc(16px + env(safe-area-inset-top));
  left: calc(16px + env(safe-area-inset-left));
  width: min(238px, 46vw);
  padding: 12px 14px;
  pointer-events: auto;
}

.toprow {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.micro {
  font-size: 9.5px;
  letter-spacing: 0.18em;
  font-weight: 700;
  color: #b9bdc9;
}

.micro.strong { color: #ffd9a8; }

.bar {
  height: 8px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
  margin: 7px 0 10px;
}

#healthFill {
  height: 100%;
  width: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, #ffb03a, #ff6b35 60%, #ff3d7f);
  box-shadow: 0 0 12px rgba(255, 105, 55, 0.5);
  transition: width 0.18s ease;
}

#healthFill.low {
  background: linear-gradient(90deg, #ff3d3d, #ff7a2f);
  animation: pulse 0.8s infinite;
}

@keyframes pulse {
  50% { opacity: 0.55; }
}

.cashrow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

