101:       { x: block.x + 12, y: block.y + 12 },
102:       { x: block.x + block.w - 12, y: block.y + block.h - 12 },
103:     );
104:     if (rng() < 0.8) {
105:       const side = Math.floor(rng() * 4);
106:       const t = 70 + rng() * (block.w - 140);
107:       let x;
108:       let y;
109:       if (side === 0) { x = block.x + t; y = block.y + 11; }
110:       else if (side === 1) { x = block.x + block.w - 11; y = block.y + t; }
111:       else if (side === 2) { x = block.x + t; y = block.y + block.h - 11; }
112:       else { x = block.x + 11; y = block.y + t; }
113:       this.streetTrees.push({ x, y, r: 7 + rng() * 5, tone: rng() });
114:     }
115:   }
116: 
117:   addPark(block) {
118:     const rng = this.rng;
119:     const { inner } = block;
120:     block.pond = rng() < 0.4
121:       ? { x: inner.x + 70 + rng() * (inner.w - 140), y: inner.y + 80 + rng() * (inner.h - 160), r: 28 + rng() * 18 }
122:       : null;
123:     const count = 7 + Math.floor(rng() * 6);
124:     for (let k = 0; k < count; k++) {
125:       const t = {
126:         x: inner.x + 24 + rng() * (inner.w - 48),
127:         y: inner.y + 24 + rng() * (inner.h - 48),
128:         r: 13 + rng() * 11,
129:         tone: rng(),
130:       };
131:       const cx = inner.x + inner.w / 2;
132:       const cy = inner.y + inner.h / 2;
133:       if (Math.abs(t.x - cx) < 34 || Math.abs(t.y - cy) < 34) continue;
134:       if (block.pond && Math.hypot(t.x - block.pond.x, t.y - block.pond.y) < block.pond.r + t.r + 8) continue;
135:       this.trees.push(t);
136:     }
137:   }
138: 
139:   addLot(block) {
140:     const rng = this.rng;
141:     const { inner } = block;
142:     const rows = 2;
143:     const cols = 4;
144:     const cw = inner.w / cols;
145:     const ch = inner.h / rows;
146:     block.stalls = [];
147:     for (let r = 0; r < rows; r++) {
148:       for (let c = 0; c < cols; c++) {
149:         const cx = inner.x + cw * (c + 0.5);
150:         const cy = inner.y + ch * (r + 0.5);
151:         const angle = r === 0 ? Math.PI / 2 : -Math.PI / 2;
152:         block.stalls.push({ x: cx, y: cy, angle });
153:         if (rng() < 0.55) this.spots.push({ x: cx, y: cy, angle });
154:       }
155:     }
156:   }
157: 
158:   addBuildings(block) {
159:     const rng = this.rng;
160:     const { inner } = block;
161:     const zone = { x: inner.x + 6, y: inner.y + 6, w: inner.w - 12, h: inner.h - 12 };
162:     const layouts = [
163:       [[0, 0, 1, 1]],
164:       [[0, 0, 1, 0.5], [0, 0.5, 1, 0.5]],
165:       [[0, 0, 0.5, 1], [0.5, 0, 0.5, 1]],
166:       [[0, 0, 0.5, 0.5], [0.5, 0, 0.5, 0.5], [0, 0.5, 0.5, 0.5], [0.5, 0.5, 0.5, 0.5]],
167:       [[0, 0, 1 / 3, 0.5], [1 / 3, 0, 1 / 3, 0.5], [2 / 3, 0, 1 / 3, 0.5],
168:         [0, 0.5, 3 / 4, 0.5], [0.75, 0.5, 0.25, 0.5]],
169:       [[0, 0, 0.5, 0.34], [0.5, 0, 0.5, 0.34], [0, 0.34, 0.5, 0.33],
170:         [0.5, 0.34, 0.5, 0.33], [0, 0.67, 0.5, 0.33], [0.5, 0.67, 0.5, 0.33]],
171:     ];
172:     const layout = layouts[Math.floor(rng() * layouts.length)];
173:     const gap = 14 + rng() * 10;
174: 
175:     for (const [lx, ly, lw, lh] of layout) {
176:       let x = zone.x + lx * zone.w;
177:       let y = zone.y + ly * zone.h;
178:       let w = lw * zone.w;
179:       let h = lh * zone.h;
180:       const padX = gap * (lx === 0 ? 0 : 0.5);
181:       const padY = gap * (ly === 0 ? 0 : 0.5);
182:       x += padX; y += padY;
183:       w -= padX + (lx + lw >= 0.999 ? 0 : gap * 0.5);
184:       h -= padY + (ly + lh >= 0.999 ? 0 : gap * 0.5);
185:       if (w < 54 || h < 54) continue;
186:       const shrink = 2 + rng() * 5;
187:       x += shrink; y += shrink; w -= shrink * 2; h -= shrink * 2;
188:       const stories = 1 + Math.floor(rng() * 5);
189:       const color = BUILDING_COLORS[Math.floor(rng() * BUILDING_COLORS.length)];
190:       const b = {
191:         x, y, w, h, stories, color,
192:         roof: shade(color, -34),
193:         edge: shade(color, 36),
194:         south: shade(color, -58),
195:         east: shade(color, -40),
196:         props: [],
197:         sign: null,
198:         lit: rng() < 0.55,
199:         helipad: rng() < 0.06 && w > 130 && h > 130,
200:         stain: rng(),
201:       };
202:       const propCount = 2 + Math.floor(rng() * 4);
203:       for (let p = 0; p < propCount; p++) {
204:         if (w < 90 || h < 90) break;
205:         const kindRoll = rng();
206:         b.props.push({
207:           x: x + 12 + rng() * (w - 56),
208:           y: y + 12 + rng() * (h - 56),
209:           w: 8 + rng() * 14,
210:           h: 6 + rng() * 11,
211:           kind: kindRoll < 0.22 ? 'tank' : kindRoll < 0.32 ? 'glass' : 'ac',
212:         });
213:       }
214:       if (rng() < 0.12 && w > 90) {
215:         b.sign = {
216:           color: rng() < 0.5 ? '#ff4d9d' : rng() < 0.5 ? '#34d6ff' : '#ffc857',
217:           x: x + 12,
218:           y: y + 6,
219:           w: 34 + rng() * 30,
220:         };
221:       }
222:       this.buildings.push(b);
223:       const key = this.bucketKey(block.i, block.j);
224:       if (!this.buckets.has(key)) this.buckets.set(key, []);
225:       this.buckets.get(key).push(b);
226:     }
227:   }
228: 
229:   buildingsNear(x, y) {
230:     const bi = Math.floor(x / CELL);
231:     const bj = Math.floor(y / CELL);
232:     let out = null;
233:     for (let j = bj - 1; j <= bj + 1; j++) {
234:       for (let i = bi - 1; i <= bi + 1; i++) {
235:         const arr = this.buckets.get(this.bucketKey(i, j));
236:         if (arr) out = out ? out.concat(arr) : arr;
237:       }
238:     }
239:     return out || [];
240:   }
241: 
242:   // Push a circle out of every building it overlaps. Returns corrected position.
243:   resolveCircle(x, y, r) {
244:     let hit = false;
245:     const list = this.buildingsNear(x, y);
246:     for (let k = 0; k < list.length; k++) {
247:       const b = list[k];
248:       const nx = clamp(x, b.x, b.x + b.w);
249:       const ny = clamp(y, b.y, b.y + b.h);
250:       let dx = x - nx;
251:       let dy = y - ny;
252:       const d2 = dx * dx + dy * dy;
253:       if (d2 >= r * r) continue;
254:       hit = true;
255:       if (d2 > 0.0001) {
256:         const d = Math.sqrt(d2);
257:         x = nx + (dx / d) * r;
258:         y = ny + (dy / d) * r;
259:       } else {
260:         const left = x - b.x;
261:         const right = b.x + b.w - x;
262:         const top = y - b.y;
263:         const bottom = b.y + b.h - y;
264:         const m = Math.min(left, right, top, bottom);
265:         if (m === left) x = b.x - r;
266:         else if (m === right) x = b.x + b.w + r;
267:         else if (m === top) y = b.y - r;
268:         else y = b.y + b.h + r;
269:       }
270:     }
271:     x = clamp(x, 16, WORLD - 16);
272:     y = clamp(y, 16, WORLD - 16);
273:     return { x, y, hit };
274:   }
275: 
276:   pointBlocked(x, y, r = 10) {
277:     const list = this.buildingsNear(x, y);
278:     for (let k = 0; k < list.length; k++) {
279:       const b = list[k];
280:       if (x > b.x - r && x < b.x + b.w + r && y > b.y - r && y < b.y + b.h + r) return true;
281:     }
282:     return false;
283:   }
284: 
285:   // A random point on a road (used for traffic, cops, deliveries).
286:   randomRoadPoint(rng = Math.random) {
287:     const vertical = rng() < 0.5;
288:     const road = Math.floor(rng() * (GRID + 1));
289:     const along = 80 + rng() * (WORLD - 160);
290:     const lane = (rng() < 0.5 ? -1 : 1) * LANE;
291:     const c = road * CELL;
292:     return vertical
293:       ? { x: c + lane, y: along, road, vertical }
294:       : { x: along, y: c + lane, road, vertical };
295:   }
296: 
297:   nearestSpot(x, y) {
298:     let best = null;
299:     let bd = Infinity;
300:     for (const s of this.spots) {
301:       const d = (s.x - x) ** 2 + (s.y - y) ** 2;
302:       if (d < bd) { bd = d; best = s; }
303:     }
304:     return best;
305:   }
306: 
307:   drawGround(ctx, view) {
308:     ctx.fillStyle = '#34363d';
309:     ctx.fillRect(view.x, view.y, view.w, view.h);
310: 
311:     const i0 = Math.max(0, Math.floor(view.x / CELL) - 1);
312:     const i1 = Math.min(GRID - 1, Math.floor((view.x + view.w) / CELL) + 1);
313:     const j0 = Math.max(0, Math.floor(view.y / CELL) - 1);
314:     const j1 = Math.min(GRID - 1, Math.floor((view.y + view.h) / CELL) + 1);
315: 
316:     for (const block of this.blocks) {
317:       if (block.i < i0 || block.i > i1 || block.j < j0 || block.j > j1) continue;
318:       this.drawBlock(ctx, block, view);
319:     }
320: 
321:     this.drawMarkings(ctx, view);
322:     this.drawStreetProps(ctx, view);
323:   }
324: 
325:   drawStreetProps(ctx, view) {
326:     for (const t of this.streetTrees) {
327:       if (t.x < view.x - 30 || t.x > view.x + view.w + 30) continue;
328:       if (t.y < view.y - 30 || t.y > view.y + view.h + 30) continue;
329:       this.drawTree(ctx, t, 0.85);
330:     }
331:     for (const l of this.lamps) {
332:       if (l.x < view.x - 50 || l.x > view.x + view.w + 50) continue;
333:       if (l.y < view.y - 50 || l.y > view.y + view.h + 50) continue;
334:       ctx.fillStyle = 'rgba(255,176,90,0.055)';
335:       ctx.beginPath();
336:       ctx.arc(l.x, l.y, 42, 0, Math.PI * 2);
337:       ctx.fill();
338:       ctx.fillStyle = 'rgba(255,190,110,0.09)';
339:       ctx.beginPath();
340:       ctx.arc(l.x, l.y, 22, 0, Math.PI * 2);
341:       ctx.fill();
342:       ctx.fillStyle = 'rgba(0,0,0,0.28)';
343:       ctx.beginPath();
344:       ctx.ellipse(l.x + 2, l.y + 3, 4.5, 3.5, 0, 0, Math.PI * 2);
345:       ctx.fill();
346:       ctx.fillStyle = '#2c2e35';
347:       ctx.beginPath();
348:       ctx.arc(l.x, l.y, 3.2, 0, Math.PI * 2);
349:       ctx.fill();
350:       ctx.fillStyle = '#ffd7a0';
351:       ctx.beginPath();
352:       ctx.arc(l.x, l.y, 1.6, 0, Math.PI * 2);
353:       ctx.fill();
354:     }
355:     for (const m of this.manholes) {
356:       if (m.x < view.x - 20 || m.x > view.x + view.w + 20) continue;
357:       if (m.y < view.y - 20 || m.y > view.y + view.h + 20) continue;
358:       ctx.fillStyle = '#26282e';
359:       ctx.beginPath();
360:       ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
361:       ctx.fill();
362:       ctx.strokeStyle = 'rgba(160,160,165,0.22)';
363:       ctx.lineWidth = 1;
364:       ctx.stroke();
365:     }
366:   }
367: 
368:   drawTree(ctx, t, scale = 1) {
369:     const r = t.r * scale;
370:     ctx.fillStyle = 'rgba(0,0,0,0.3)';
371:     ctx.beginPath();
372:     ctx.ellipse(t.x + 7, t.y + 8, r * 1.05, r * 0.9, 0, 0, Math.PI * 2);
373:     ctx.fill();
374:     ctx.fillStyle = '#3d6440';
375:     ctx.beginPath();
376:     ctx.arc(t.x, t.y, r, 0, Math.PI * 2);
377:     ctx.fill();
378:     ctx.fillStyle = t.tone > 0.5 ? '#568a55' : '#4e7d4f';
379:     ctx.beginPath();
380:     ctx.arc(t.x - r * 0.22, t.y - r * 0.22, r * 0.82, 0, Math.PI * 2);
381:     ctx.fill();
382:     ctx.fillStyle = 'rgba(160,210,140,0.35)';
383:     ctx.beginPath();
384:     ctx.arc(t.x - r * 0.35, t.y - r * 0.35, r * 0.32, 0, Math.PI * 2);
385:     ctx.fill();
386:   }
387: 
388:   drawBlock(ctx, block, view) {
389:     const { x, y, w, h, inner } = block;
390:     // Sidewalk slab
391:     ctx.fillStyle = '#847e73';
392:     ctx.fillRect(x, y, w, h);
393:     ctx.fillStyle = '#736e64';
394:     ctx.fillRect(x + 3, y + 3, w - 6, h - 6);
395:     // Curb line
396:     ctx.strokeStyle = 'rgba(20,20,24,0.35)';
397:     ctx.lineWidth = 2;
398:     ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
399: 
400:     // Pavement joints along the footpath
401:     ctx.strokeStyle = 'rgba(20,20,24,0.10)';
402:     ctx.lineWidth = 1;
403:     ctx.beginPath();
404:     for (let t = x + 18; t < x + w - 4; t += 28) {
405:       ctx.moveTo(t, y + 4);
406:       ctx.lineTo(t, y + SIDEWALK - 2);
407:       ctx.moveTo(t, y + h - SIDEWALK + 2);
408:       ctx.lineTo(t, y + h - 4);
409:     }
410:     for (let t = y + 18; t < y + h - 4; t += 28) {
411:       ctx.moveTo(x + 4, t);
412:       ctx.lineTo(x + SIDEWALK - 2, t);
413:       ctx.moveTo(x + w - SIDEWALK + 2, t);
414:       ctx.lineTo(x + w - 4, t);
415:     }
416:     ctx.stroke();
417: 
418:     if (block.type === 'park') {
419:       this.drawPark(ctx, block);
420:     } else if (block.type === 'lot') {
421:       ctx.fillStyle = '#3b3e46';
422:       ctx.fillRect(inner.x, inner.y, inner.w, inner.h);
423:       ctx.strokeStyle = 'rgba(226,226,210,0.35)';
424:       ctx.lineWidth = 2;
425:       if (block.stalls) {
426:         for (const s of block.stalls) {
427:           ctx.save();
428:           ctx.translate(s.x, s.y);
429:           ctx.rotate(s.angle);
430:           ctx.strokeRect(-24, -30, 48, 60);
431:           ctx.restore();
432:         }
433:       }
434:       ctx.strokeStyle = 'rgba(226,226,210,0.5)';
435:       ctx.strokeRect(inner.x + 2, inner.y + 2, inner.w - 4, inner.h - 4);
436:     } else {
437:       ctx.fillStyle = '#5f5d58';
438:       ctx.fillRect(inner.x, inner.y, inner.w, inner.h);
439:       ctx.strokeStyle = 'rgba(0,0,0,0.12)';
440:       ctx.lineWidth = 1;
441:       for (let gx = inner.x; gx < inner.x + inner.w; gx += 40) {
442:         ctx.beginPath();
443:         ctx.moveTo(gx, inner.y);
444:         ctx.lineTo(gx, inner.y + inner.h);
445:         ctx.stroke();
446:       }
447:       for (const b of this.buildings) {
448:         if (b.x < block.x - 5 || b.x > block.x + block.w) continue;
449:         if (b.y < block.y - 5 || b.y > block.y + block.h) continue;
450:         this.drawBuilding(ctx, b, view);
451:       }
452:     }
453:   }
454: 
455:   drawPark(ctx, block) {
456:     const { inner } = block;
457:     ctx.fillStyle = '#446b4c';
458:     ctx.fillRect(inner.x, inner.y, inner.w, inner.h);
459:     ctx.fillStyle = '#4b7654';
460:     ctx.fillRect(inner.x + 4, inner.y + 4, inner.w - 8, inner.h - 8);
461: 
462:     // paths
463:     ctx.fillStyle = '#8c8375';
464:     ctx.fillRect(inner.x + inner.w / 2 - 13, inner.y, 26, inner.h);
465:     ctx.fillRect(inner.x, inner.y + inner.h / 2 - 13, inner.w, 26);
466: 
467:     if (block.pond) {
468:       const p = block.pond;
469:       ctx.fillStyle = '#2c5566';
470:       ctx.beginPath();
471:       ctx.ellipse(p.x, p.y, p.r * 1.15, p.r * 0.85, 0.2, 0, Math.PI * 2);
472:       ctx.fill();
473:       ctx.strokeStyle = 'rgba(150,220,230,0.25)';
474:       ctx.lineWidth = 2;
475:       ctx.stroke();
476:     }
477: 
478:     for (const t of this.trees) {
479:       if (t.x < block.x || t.x > block.x + block.w || t.y < block.y || t.y > block.y + block.h) continue;
480:       this.drawTree(ctx, t);
481:     }
482:   }
483: 
484:   drawBuilding(ctx, b, view) {
485:     if (b.x > view.x + view.w + 60 || b.x + b.w < view.x - 60) return;
486:     if (b.y > view.y + view.h + 60 || b.y + b.h < view.y - 60) return;
487: 
488:     const d = 3 + b.stories * 2.6;
489: 
490:     // Long late-afternoon shadow
491:     ctx.fillStyle = 'rgba(8, 8, 12, 0.34)';
492:     ctx.fillRect(b.x + d + 8, b.y + d + 9, b.w + 2, b.h + 2);
493: 
494:     // South facade (the strip below the footprint)
495:     ctx.fillStyle = b.south;
496:     ctx.beginPath();
497:     ctx.moveTo(b.x, b.y + b.h);
498:     ctx.lineTo(b.x + b.w, b.y + b.h);
499:     ctx.lineTo(b.x + b.w + d, b.y + b.h + d);
500:     ctx.lineTo(b.x + d, b.y + b.h + d);
501:     ctx.closePath();
502:     ctx.fill();
503: 
504:     // East facade
505:     ctx.fillStyle = b.east;
506:     ctx.beginPath();
507:     ctx.moveTo(b.x + b.w, b.y);
508:     ctx.lineTo(b.x + b.w, b.y + b.h);
509:     ctx.lineTo(b.x + b.w + d, b.y + b.h + d);
510:     ctx.lineTo(b.x + b.w + d, b.y + d);
511:     ctx.closePath();
512:     ctx.fill();
513: 
514:     // Roof slab
515:     ctx.fillStyle = b.color;
516:     ctx.fillRect(b.x, b.y, b.w, b.h);
517:     ctx.fillStyle = b.roof;
518:     ctx.fillRect(b.x + 6, b.y + 6, b.w - 12, b.h - 12);
519: 
520:     // Parapet
521:     ctx.strokeStyle = b.edge;
522:     ctx.lineWidth = 2.5;
523:     ctx.strokeRect(b.x + 1.2, b.y + 1.2, b.w - 2.4, b.h - 2.4);
524: 
525:     // Rooftop texture
526:     ctx.strokeStyle = 'rgba(255,255,255,0.035)';
527:     ctx.lineWidth = 1;
528:     ctx.beginPath();
529:     for (let gx = b.x + 18; gx < b.x + b.w - 10; gx += 30) {
530:       ctx.moveTo(gx, b.y + 8);
531:       ctx.lineTo(gx, b.y + b.h - 8);
532:     }
533:     for (let gy = b.y + 18; gy < b.y + b.h - 10; gy += 30) {
534:       ctx.moveTo(b.x + 8, gy);
535:       ctx.lineTo(b.x + b.w - 8, gy);
536:     }
537:     ctx.stroke();
538: 
539:     // Facade windows (south strip)
540:     const rows = Math.max(1, Math.min(3, Math.floor(d / 5)));
541:     for (let r = 0; r < rows; r++) {
542:       const frac = (r + 0.55) / rows;
543:       const fy = b.y + b.h + d * frac;
544:       const fx = b.x + d * frac;
545:       for (let wx = fx + 9; wx < fx + b.w - 12; wx += 21) {
546:         const lit = b.lit && (Math.floor(wx + b.y) % 3 !== 0);
547:         ctx.fillStyle = lit ? 'rgba(255,214,150,0.72)' : 'rgba(24,28,38,0.72)';
548:         ctx.fillRect(wx, fy - 1.5, 8, 3);
549:       }
550:     }
551: 
552:     // Rooftop props
553:     for (const p of b.props) {
554:       ctx.fillStyle = 'rgba(0,0,0,0.25)';
555:       ctx.fillRect(p.x + 3, p.y + 3, p.w, p.h);
556:       if (p.kind === 'glass') {
557:         ctx.fillStyle = 'rgba(60,90,110,0.85)';
558:         ctx.fillRect(p.x, p.y, p.w, p.h);
559:         ctx.strokeStyle = 'rgba(200,230,245,0.35)';
560:         ctx.lineWidth = 1;
561:         ctx.strokeRect(p.x + 1, p.y + 1, p.w - 2, p.h - 2);
562:         continue;
563:       }
564:       ctx.fillStyle = p.kind === 'tank' ? '#9c8f7d' : '#8b9095';
565:       ctx.fillRect(p.x, p.y, p.w, p.h);
566:       ctx.fillStyle = 'rgba(255,255,255,0.18)';
567:       ctx.fillRect(p.x, p.y, p.w, 2);
568:       if (p.kind === 'ac') {
569:         ctx.strokeStyle = 'rgba(30,30,35,0.4)';
570:         ctx.strokeRect(p.x + 2.5, p.y + 2.5, p.w - 5, p.h - 5);
