drawScreenFX() {
  if (this.state === 'menu') return;
  const ui = this.ui();
  const danger = this.wanted > 0 ? 0.55 + 0.2 * Math.sin(this.time * 4) : 0;
  if (ui.dangerFx && Math.abs((this._lastDangerFx || 0) - danger) > 0.015) {
    this._lastDangerFx = danger;
    ui.dangerFx.style.opacity = danger.toFixed(2);
  }
  const damage = Math.min(1, this.damageFlash * 1.15);
  if (ui.damageFx && Math.abs((this._lastDamageFx || 0) - damage) > 0.02) {
    this._lastDamageFx = damage;
    ui.damageFx.style.opacity = damage.toFixed(2);
  }
},

