drawScreenFX() {
  if (this.state === 'menu') return;
  const ctx = this.ctx;
  const { cssW, cssH } = this;
  if (this.damageFlash > 0.01) {
    const g = ctx.createRadialGradient(cssW / 2, cssH / 2, Math.min(cssW, cssH) * 0.28, cssW / 2, cssH / 2, Math.max(cssW, cssH) * 0.72);
    g.addColorStop(0, 'rgba(150,0,0,0)');
