    ctx.fillStyle = g;
    ctx.fillRect(0, 0, cssW, cssH);
  }
  if (this.wanted > 0) {
    const pulse = 0.05 + 0.03 * Math.sin(this.time * 4);
    const g = ctx.createRadialGradient(cssW / 2, cssH / 2, Math.min(cssW, cssH) * 0.4, cssW / 2, cssH / 2, Math.max(cssW, cssH) * 0.75);
    g.addColorStop(0, 'rgba(60,80,255,0)');
    g.addColorStop(1, `rgba(70,90,255,${pulse})`);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, cssW, cssH);
  }
},

